script:
frappe.ui.form.on('Workspace', {
    refresh: function(frm) {
        // ดักจับเศษพารามิเตอร์ที่แนบมาจากไอคอนลัดใน hooks.py
        if (window.location.href.indexOf('action=select_branch') !== -1) {

            setTimeout(() => {
                if (typeof frappe.ui.toolbar.setup_session_defaults === "function") {

                    // 1. บังคับเปิดหน้าต่างระบบ Session Defaults ให้เลือกสาขา
                    frappe.ui.toolbar.setup_session_defaults();

                    // ล้างพารามิเตอร์บนช่อง URL ทันทีเพื่อให้หน้าเว็บสะอาด
                    window.history.replaceState({}, document.title, window.location.pathname);

                    // 2. แก้ปัญหา Forced Reflow บล็อก:
                    // ดักจับเมื่อระบบเซฟค่าสาขาและส่งข้อมูลเครือข่ายเสร็จสิ้น
                    $(document).ajaxComplete(function(event, xhr, settings) {
                        if (settings.url.indexOf('frappe.core.doctype.user.user.set_defaults') !== -1 || 
                            settings.url.indexOf('set_session_defaults') !== -1) {

                            // ใช้การหน่วงเวลาสั้นๆ เพื่อให้ระบบ Core บันทึกค่าลงฐานข้อมูลเสร็จสมบูรณ์ก่อน
                            setTimeout(() => {
                                // คำสั่งระดับน็อคเอาท์: บังคับเปิดหน้าต่างระบบ /apps ขึ้นมาทับเบราว์เซอร์เดิมทันที
                                // วิธีนี้จะทลายปัญหา Forced Reflow ทิ้ง 100% เพราะถือเป็นการสั่งโหลดตัวเว็บใหม่ทั้งระบบจากหน้าแรกครับ
                                window.location.open = window.location.assign('/apps');
                            }, 300);
                        }
                    });
                }
            }, 500);
        }
    }
});

// เขียนคำสั่งแบบสากล ครอบคลุมทั้งระบบการเปลี่ยนหน้าจอ Desk
$(document).on('page-change', function() {
    let current_route = frappe.get_route();

    // ตรวจสอบเงื่อนไข: หากผู้ใช้อยู่หน้าแรก (Workspace) และมีสัญญาณบังคับล็อกอินเลือกสาขาจากฝั่ง Python
    if (current_route && current_route === 'workspace' && frappe.boot.force_branch_dialog === 1) {

        // หน่วงเวลาสั้นๆ เพื่อรอให้ระบบ Core UI ของเวอร์ชัน 16 โหลดวัตถุหน้าจอเสร็จสมบูรณ์
        setTimeout(() => {
            if (typeof frappe.ui.toolbar.setup_session_defaults === "function") {

                // สั่งระเบิดป็อปอัปสลับสาขามาตรฐานของระบบขึ้นมาทันที
                frappe.ui.toolbar.setup_session_defaults();

                // ล้างค่าตัวแปรทิ้งชั่วคราว เพื่อไม่ให้ป็อปอัปเด้งซ้ำซ้อนตอนพนักงานกดเปลี่ยนหน้าย่อย
                frappe.boot.force_branch_dialog = 0;
            }
        }, 500); 
    }
});

// ============================================================
// BOOK ORDER
// ============================================================

frappe.ui.form.on("Book Order", {

    refresh: function(frm) {
        calculate_book_order_total(frm);
    },

    validate: function(frm) {
        calculate_book_order_total(frm);
    }
});


// ============================================================
// BOOKS ORDER ITEM
// ============================================================

frappe.ui.form.on("Books Order Item", {

    // --------------------------------------------------------
    // ราคาเปลี่ยน
    // --------------------------------------------------------
    price: function(frm, cdt, cdn) {

        //console.log("PRICE:", cdn);

        calculate_book_order_total(frm);
    },


    // --------------------------------------------------------
    // จำนวนเปลี่ยน
    // --------------------------------------------------------
    quantity: function(frm, cdt, cdn) {

        //console.log("QUANTITY:", cdn);

        calculate_book_order_total(frm);
    },


    // --------------------------------------------------------
    // ก่อนลบ Row
    // --------------------------------------------------------
    before_items_remove: function(frm, cdt, cdn) {

        //console.log("BEFORE REMOVE:", cdn);

        // สำคัญ:
        // ต้องรอให้ Frappe ลบ Row ออกจาก frm.doc.items
        // ก่อนจึงคำนวณใหม่
        setTimeout(function() {

        //    console.log(
        //        "AFTER REMOVE ITEMS:",
        //        (frm.doc.items || []).length
        //    );

            calculate_book_order_total(frm);

        }, 100);
    }
});


// ============================================================
// คำนวณ Total Price + Total Amount
// ============================================================

function calculate_book_order_total(frm) {

    let total_amount = 0;

    let items = frm.doc.items || [];

    //console.log("================================");
    //console.log("CALCULATE");
    //console.log("ITEM COUNT:", items.length);


    // --------------------------------------------------------
    // วนทุก Row
    // --------------------------------------------------------

    items.forEach(function(row) {

        let price = flt(row.price);
        let quantity = flt(row.quantity);

        let total_price = price * quantity;


        // Total Price ของ Row
        row.total_price = total_price;


        // รวม Total Amount
        total_amount += total_price;


        //console.log(
        //    "ROW:",
        //    row.name,
        //    "PRICE:",
        //    price,
        //    "QTY:",
        //    quantity,
        //    "TOTAL:",
        //    total_price
        //);
    });


    // --------------------------------------------------------
    // Total Amount ของ Book Order
    // --------------------------------------------------------

    //console.log("TOTAL AMOUNT:", total_amount);

    frm.doc.total_amount = total_amount;


    // --------------------------------------------------------
    // Refresh
    // --------------------------------------------------------

    frm.refresh_field("items");

    frm.refresh_field("total_amount");
}
